import React, { useState, useRef, useEffect } from "react";

export function DropdownMenu() {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) setIsOpen(false);
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);
  return (
    <div className="relative inline-block text-left" ref={ref}>
      <button onClick={() => setIsOpen(!isOpen)} aria-expanded={isOpen} className="px-3.5 py-1.5 rounded-[8px] border border-border bg-card text-xs font-medium text-foreground flex items-center gap-2"><span>Options</span><span className="text-[10px]">▼</span></button>
      {isOpen && (
        <div className="absolute left-0 mt-2 w-48 rounded-lg border border-border bg-card shadow-lg py-1 z-20 text-xs">
          <button onClick={() => setIsOpen(false)} className="w-full text-left px-3 py-1.5 text-foreground hover:bg-muted">Edit project</button>
          <button onClick={() => setIsOpen(false)} className="w-full text-left px-3 py-1.5 text-foreground hover:bg-muted">Duplicate</button>
          <div className="h-px bg-border my-1" />
          <button onClick={() => setIsOpen(false)} className="w-full text-left px-3 py-1.5 text-red-600 hover:bg-red-500/10">Delete</button>
        </div>
      )}
    </div>
  );
}
